package com.theseusoft.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.web.authentication.WebAuthenticationDetailsSource; import org.springframework.web.filter.OncePerRequestFilter; import org.springframework.stereotype.Component;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter {
 private final JwtService jwt; public JwtAuthenticationFilter(JwtService jwt){this.jwt=jwt;}
 @Override protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res, FilterChain chain) throws ServletException, IOException { String auth=req.getHeader("Authorization"); if(auth!=null&&auth.startsWith("Bearer ")){String token=auth.substring(7);if(jwt.valid(token)&&SecurityContextHolder.getContext().getAuthentication()==null){var authentication=new UsernamePasswordAuthenticationToken(jwt.subject(token),null,jwt.roles(token).stream().map(SimpleGrantedAuthority::new).toList()); authentication.setDetails(new WebAuthenticationDetailsSource().buildDetails(req)); SecurityContextHolder.getContext().setAuthentication(authentication);}} chain.doFilter(req,res); }
}
